import{_ as t,o as a,c as n,a as r}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"Qwen（通义千问）学习笔记：从开源大模型到全栈多模态AI生态","description":"","frontmatter":{},"headers":[],"relativePath":"ai/models/domestic/qwen.md","filePath":"ai/models/domestic/qwen.md"}'),o={name:"ai/models/domestic/qwen.md"};function d(i,e,l,h,s,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="qwen-通义千问-学习笔记-从开源大模型到全栈多模态ai生态" tabindex="-1">Qwen（通义千问）学习笔记：从开源大模型到全栈多模态AI生态 <a class="header-anchor" href="#qwen-通义千问-学习笔记-从开源大模型到全栈多模态ai生态" aria-label="Permalink to &quot;Qwen（通义千问）学习笔记：从开源大模型到全栈多模态AI生态&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>Qwen（发音“chwen”，取自中文“通义千问”）是阿里巴巴集团通义实验室开发的开源大语言模型与多模态AI系统系列。自2023年8月首次发布以来，Qwen已发展成为全球最大的开源AI生态系统之一，涵盖文本生成、代码、视觉、音频、语音、图像生成和实时多模态交互等全栈能力。</p><p>截至2026年初，Qwen系列衍生模型数量突破20万款，全球下载量超10亿次，成为全球首个达成此目标的开源大模型。超100万家客户接入通义大模型，在中国企业级大模型调用市场中占比第一。2026年3月，阿里巴巴宣布将AI的总称和核心品牌统一为“千问”。</p><h2 id="二、发展历程" tabindex="-1">二、发展历程 <a class="header-anchor" href="#二、发展历程" aria-label="Permalink to &quot;二、发展历程&quot;">​</a></h2><h3 id="_2-1-技术铺垫期-2014–2022" tabindex="-1">2.1 技术铺垫期（2014–2022） <a class="header-anchor" href="#_2-1-技术铺垫期-2014–2022" aria-label="Permalink to &quot;2.1 技术铺垫期（2014–2022）&quot;">​</a></h3><p>阿里巴巴从2014年成立iDST研究院开始投入AI核心技术研发。2020年，多模态大模型M6项目启动，2021年11月其参数从万亿跃迁至10万亿，规模超过谷歌、微软此前发布的万亿级模型。2022年，通义实验室正式成立。</p><h3 id="_2-2-正式发布与开源-2023" tabindex="-1">2.2 正式发布与开源（2023） <a class="header-anchor" href="#_2-2-正式发布与开源-2023" aria-label="Permalink to &quot;2.2 正式发布与开源（2023）&quot;">​</a></h3><p>2022年9月，“通义”系列大模型正式发布，标志着通义千问项目的正式启动。2023年4月，通义千问大语言模型以测试版形式发布并启动邀请测试；同年8月，Qwen第一代开源模型正式推出，为社区提供了从预训练到对齐的完整技术栈范例。</p><h3 id="_2-3-快速迭代期-2024–2026" tabindex="-1">2.3 快速迭代期（2024–2026） <a class="header-anchor" href="#_2-3-快速迭代期-2024–2026" aria-label="Permalink to &quot;2.3 快速迭代期（2024–2026）&quot;">​</a></h3><p>Qwen系列经历了密集的版本迭代：2024年2月发布Qwen1.5实现全系列32K上下文和对齐技术升级；2024年6月Qwen2实现性能大幅提升并首次引入MoE架构；2024年9月Qwen2.5将代码能力大幅强化并扩展至18T tokens预训练数据。2025年进入多模态爆发期，陆续推出Qwen2-VL视觉模型、Qwen2.5-Max、QwQ-32B推理模型以及Qwen3系列。2026年2月推出Qwen3.5旗舰系列。</p><p>2026年1月，Qwen与夸克、UC浏览器等应用完成鸿蒙生态功能整合。2026年米兰冬奥会采用该模型构建首个官方大模型，应用于赛事服务与多语言智能问答。</p><h2 id="三、核心技术架构" tabindex="-1">三、核心技术架构 <a class="header-anchor" href="#三、核心技术架构" aria-label="Permalink to &quot;三、核心技术架构&quot;">​</a></h2><h3 id="_3-1-整体设计理念" tabindex="-1">3.1 整体设计理念 <a class="header-anchor" href="#_3-1-整体设计理念" aria-label="Permalink to &quot;3.1 整体设计理念&quot;">​</a></h3><p>Qwen系列基于Transformer解码器架构，核心技术演进沿着两条主轴推进：一是训练数据规模从3T tokens逐步扩展至36T tokens；二是架构与训练范式从GQA、MoE到长上下文、强化学习持续突破。模型兼容RoPE旋转位置编码、SwiGLU激活函数、RMSNorm归一化、FlashAttention加速等主流技术组件。</p><h3 id="_3-2-混合专家-moe-架构" tabindex="-1">3.2 混合专家（MoE）架构 <a class="header-anchor" href="#_3-2-混合专家-moe-架构" aria-label="Permalink to &quot;3.2 混合专家（MoE）架构&quot;">​</a></h3><p>Qwen 3.0及后续版本全面引入MoE架构，其核心是“稀疏激活”：模型拥有巨大的总参数量，但在推理时仅激活其中一小部分，实现“大参数容量 + 低推理成本”的双重优势。例如Qwen2.5-72B采用128个专家模块，每个专家负责特定领域的语义处理，推理时仅激活约15%的参数（约10.8B），却能保持全参数模型级的性能水平。</p><p>主要MoE旗舰模型包括：</p><table tabindex="0"><thead><tr><th>模型</th><th>总参数量</th><th>激活参数量</th><th>特点</th></tr></thead><tbody><tr><td>Qwen3.5</td><td>397B</td><td>17B</td><td>旗舰级，支持201种语言和原生多模态</td></tr><tr><td>Qwen3.5-Plus</td><td>397B</td><td>17B</td><td>API旗舰，推理效率提升19倍</td></tr><tr><td>Qwen3-Coder</td><td>480B</td><td>35B</td><td>编程专项旗舰</td></tr><tr><td>Qwen3</td><td>235B</td><td>22B</td><td>第三代标准MoE架构</td></tr><tr><td>Qwen2.5-72B</td><td>72B</td><td>~10.8B</td><td>开源MoE代表性模型</td></tr><tr><td>Qwen2.5-Max</td><td>~100B</td><td>~30B</td><td>API旗舰，超20T tokens训练</td></tr><tr><td>Qwen3.5-35B</td><td>35B</td><td>3B</td><td>轻量高效，推理速度极快</td></tr><tr><td>Qwen3.5-122B</td><td>122B</td><td>10B</td><td>中等规模MoE</td></tr></tbody></table><p>MoE架构的核心优势在于：</p><ul><li><strong>高效推理</strong>：稀疏激活机制仅调用相关专家模块，推理成本较同等规模密集模型降低约10倍；</li><li><strong>知识分治</strong>：不同专家处理不同领域任务，如语言理解专家、数学计算专家等；</li><li><strong>动态路由</strong>：通过动态路由机制将输入数据分配至最适合的专家子网络，计算效率较传统稠密模型提升达40%。</li></ul><h3 id="_3-3-长上下文处理" tabindex="-1">3.3 长上下文处理 <a class="header-anchor" href="#_3-3-长上下文处理" aria-label="Permalink to &quot;3.3 长上下文处理&quot;">​</a></h3><p>Qwen系列在长上下文能力上持续突破。Qwen2.5-Turbo首次将上下文长度从128K tokens扩展至1M tokens，约等于100万个英文单词或150万个汉字，相当于10本长篇小说、150小时演讲稿或3万行代码。推理速度方面，团队利用稀疏注意力机制将注意力部分计算量压缩约12.5倍，处理1M tokens的首字返回时间从4.9分钟降至68秒，实现4.3倍加速。</p><p>该模型在1M长度的Passkey Retrieval任务中准确率达到100%，在长文本评测集RULER上获得93.1分，超越GPT-4的91.6分。在LV-Eval、LongBench-Chat等更接近真实场景的长文本任务中也超越了GPT-4o-mini。</p><p>Qwen3.6系列进一步优化，支持256K原生上下文并采用Context Folding（超过阈值时压缩旧工具响应）和WideSearch模式（智能管理长上下文信息）等高级处理机制。Qwen3.5全系列支持262K原生上下文，可扩展至1M。</p><h3 id="_3-4-预训练数据规模" tabindex="-1">3.4 预训练数据规模 <a class="header-anchor" href="#_3-4-预训练数据规模" aria-label="Permalink to &quot;3.4 预训练数据规模&quot;">​</a></h3><p>Qwen模型的预训练数据规模经历持续跃升：Qwen初代约3T tokens；Qwen2.5达到18T tokens，覆盖中英文多语言数据；Qwen3进一步扩展至36T tokens，覆盖119种语言，并对数学、代码、STEM推理做了额外强化。Qwen2.5-72B采用2.3T多样化语料库，通过数据去重和质量过滤将有效数据密度提升40%。Qwen3-Coder则采用7.5T tokens的预训练数据，其中代码占比70%。</p><h3 id="_3-5-量化与部署优化" tabindex="-1">3.5 量化与部署优化 <a class="header-anchor" href="#_3-5-量化与部署优化" aria-label="Permalink to &quot;3.5 量化与部署优化&quot;">​</a></h3><p>Qwen系列在模型压缩和量化方面同样表现突出。Qwen2.5-72B通过量化感知训练技术，在INT4精度下仅损失1.2%准确率，推理速度较FP16提升3倍。Qwen2.5-VL采用8bit量化技术使模型参数量减少60%而性能保持95%以上。Qwen3.5全系列支持GGUF、AWQ、GPTQ等多种量化格式，覆盖边缘设备到云端服务器的全场景部署需求。</p><h3 id="_3-6-训练对齐技术" tabindex="-1">3.6 训练对齐技术 <a class="header-anchor" href="#_3-6-训练对齐技术" aria-label="Permalink to &quot;3.6 训练对齐技术&quot;">​</a></h3><p>在模型对齐方面，Qwen系列持续引入先进的训练技术。Qwen1.5开始采用DPO（直接偏好优化）和PPO（近端策略优化）对齐策略。Qwen2.5引入多阶段SFT（监督微调）+ DPO + GRPO（组相对策略优化）的复合对齐流程。Qwen3进一步引入“思考/非思考”双模式统一框架，支持灵活的思考预算配置，并通过强弱蒸馏技术提升推理效率。</p><p>在MoE架构训练中，Qwen2.5引入了动态损失缩放技术，通过监控每个专家的梯度范数动态调整损失缩放因子，解决MoE架构中的梯度消失问题。例如，在代码生成任务中，负责Python语法的专家模块通过动态损失缩放，将语法错误率从3.2%降至1.5%。</p><h2 id="四、多模态模型体系" tabindex="-1">四、多模态模型体系 <a class="header-anchor" href="#四、多模态模型体系" aria-label="Permalink to &quot;四、多模态模型体系&quot;">​</a></h2><h3 id="_4-1-qwen-vl视觉语言模型" tabindex="-1">4.1 Qwen-VL视觉语言模型 <a class="header-anchor" href="#_4-1-qwen-vl视觉语言模型" aria-label="Permalink to &quot;4.1 Qwen-VL视觉语言模型&quot;">​</a></h3><p>Qwen视觉语言模型经历了从Qwen-VL到Qwen2-VL再到Qwen3-VL的三代演进。</p><p><strong>Qwen-VL（2023）</strong> ：初代通过联合训练文本与视觉编码器，实现了图像描述、视觉问答等基础功能，采用Transformer双塔结构，视觉编码器使用Swin Transformer。</p><p><strong>Qwen2-VL（2024）</strong> ：实现了关键技术跃迁。它提出了Naive Dynamic Resolution机制，能够动态处理任意分辨率的图像，无需将图像分割成块，更接近模仿人类的视觉感知过程。集成了多模态旋转位置编码（M-RoPE），有效融合文本、图像、视频中的位置信息。同时采用统一的图像与视频处理范式，可理解20分钟以上的长视频，支持基于视频的问答和内容创作。Qwen2-VL分2B、8B、72B三个尺寸版本，在MathVista、DocVQA等基准测试中创下全球领先表现。</p><p><strong>Qwen3-VL（2025）</strong> ：实现了重大突破，在32项核心能力测评中超过Gemini2.5-Pro和GPT-5，支持“带图推理”和“视觉编程”——可调用抠图、搜索等工具完成推理，也可凭借一张设计草图或一段小游戏视频直接生成代码。专门增强了3D检测能力，可更准确判断物体方位、视角变化与遮挡关系，应用于具身智能场景。2025年11月，Qwen3-VL以13.5分登顶空间推理基准SpatialBench榜首，Qwen2.5-VL以12.9分位居第二，大幅领先Gemini3.0 Pro Preview（9.6分）与GPT-5.1（7.5分）。</p><p><strong>Qwen2.5-VL</strong>：核心升级聚焦于三个方面：引入对话状态跟踪机制实现上下文相关的视觉推理；新增3D点云、视频流等新型模态数据；采用8bit量化优化部署效率。</p><h3 id="_4-2-qwen全模态模型" tabindex="-1">4.2 Qwen全模态模型 <a class="header-anchor" href="#_4-2-qwen全模态模型" aria-label="Permalink to &quot;4.2 Qwen全模态模型&quot;">​</a></h3><p><strong>Qwen3.5-Omni</strong>（2026年3月发布）：原生全模态模型，可同时处理和生成文本、图像、音频和视频，支持113种语言的语音识别，在215个音频/视觉任务上达到SOTA水平。</p><p><strong>Qwen3.5系列</strong>：实现了“统一视觉-语言基础模型”，所有模型原生支持图像和视频理解，无需单独的VL变体。</p><h3 id="_4-3-图像生成与编辑" tabindex="-1">4.3 图像生成与编辑 <a class="header-anchor" href="#_4-3-图像生成与编辑" aria-label="Permalink to &quot;4.3 图像生成与编辑&quot;">​</a></h3><p><strong>Qwen-Image-2.0</strong>（2026年2月）：支持专业排版，可基于1K令牌指令生成PPT、海报、漫画等，2K原生分辨率。</p><p><strong>Qwen-Image-Edit</strong>（2025年8月）：20B参数MMDiT架构，支持精确文本编辑、对象增删移动、风格转移等，中文渲染达SOTA水平。</p><h3 id="_4-4-音频与语音模型" tabindex="-1">4.4 音频与语音模型 <a class="header-anchor" href="#_4-4-音频与语音模型" aria-label="Permalink to &quot;4.4 音频与语音模型&quot;">​</a></h3><p><strong>FunAudio系列</strong>（2025年9月发布）：专注语音识别与音频处理的专用模型系列。2026年4月推出语音识别大模型Fun-ASR1.5。</p><h2 id="五、模型体系全景" tabindex="-1">五、模型体系全景 <a class="header-anchor" href="#五、模型体系全景" aria-label="Permalink to &quot;五、模型体系全景&quot;">​</a></h2><h3 id="_5-1-纯文本语言模型" tabindex="-1">5.1 纯文本语言模型 <a class="header-anchor" href="#_5-1-纯文本语言模型" aria-label="Permalink to &quot;5.1 纯文本语言模型&quot;">​</a></h3><p>Qwen文本模型涵盖从0.5B到397B的完整参数规模：</p><table tabindex="0"><thead><tr><th>世代</th><th>发布时间</th><th>核心特点</th><th>代表规格</th></tr></thead><tbody><tr><td>Qwen 1.0</td><td>2023.08</td><td>开源基础版</td><td>7B, 14B</td></tr><tr><td>Qwen 1.5</td><td>2024.02</td><td>DPO/PPO对齐，32K上下文</td><td>0.5B~72B + MoE</td></tr><tr><td>Qwen 2</td><td>2024.06</td><td>GQA注意力，引入MoE</td><td>0.5B~72B, 57B MoE</td></tr><tr><td>Qwen 2.5</td><td>2024.09</td><td>18T tokens, 代码能力强化</td><td>0.5B~72B</td></tr><tr><td>Qwen 3</td><td>2025.05</td><td>36T tokens, 思考/非思考双模式</td><td>0.6B~72B + MoE旗舰</td></tr><tr><td>Qwen 3.5</td><td>2026.02</td><td>原生多模态，混合DeltaNet架构</td><td>0.8B~397B MoE</td></tr></tbody></table><p>各世代均包含Base（基座模型）和Instruct（指令微调）等版本，支持29种以上语言。</p><h3 id="_5-2-代码专用模型" tabindex="-1">5.2 代码专用模型 <a class="header-anchor" href="#_5-2-代码专用模型" aria-label="Permalink to &quot;5.2 代码专用模型&quot;">​</a></h3><ul><li><strong>Qwen3-Coder</strong>：480B总参数、35B激活参数，原生支持256K上下文（可扩展至1M），在真实软件工程任务SWE-Bench上达到开源模型SOTA。预训练数据7.5T tokens（代码占比70%），后训练采用Agent RL技术，可同时运行2万个独立环境进行强化学习。</li><li><strong>Qwen3-Coder-Next</strong>：2026年2月发布，在SWE-Bench上达到70.6%的得分，仅激活3B参数即可匹配Claude Sonnet 4.0级别的编码能力。</li><li><strong>Qwen Code CLI工具</strong>：配套命令行工具，可与Claude Code、Cline等编程工具协同使用。</li></ul><h3 id="_5-3-推理专项模型" tabindex="-1">5.3 推理专项模型 <a class="header-anchor" href="#_5-3-推理专项模型" aria-label="Permalink to &quot;5.3 推理专项模型&quot;">​</a></h3><ul><li><strong>QwQ-32B</strong>（2025年3月发布）：支持消费级显卡部署，通过Outcome奖励驱动的强化学习扩展训练，在数学推理和代码任务上表现出色。特点包括思维链展开和多路径验证。</li><li><strong>通义DeepResearch</strong>：300亿总参数，每令牌仅激活30亿参数，专门用于长期、深入的信息检索任务，在一系列代理搜索基准上展示了SOTA性能。</li></ul><h3 id="_5-4-向量模型与安全护卫" tabindex="-1">5.4 向量模型与安全护卫 <a class="header-anchor" href="#_5-4-向量模型与安全护卫" aria-label="Permalink to &quot;5.4 向量模型与安全护卫&quot;">​</a></h3><ul><li><strong>Qwen3-Embedding系列</strong>：0.6B/4B/8B版本，用于文本向量化与检索。</li><li><strong>Qwen3-VL-Embedding &amp; Qwen3-VL-Reranker</strong>：2026年1月开源，2B/8B参数，支持多模态检索和跨模态重排序。</li><li><strong>Qwen3Guard</strong>（2025年10月）：安全护卫模型，支持三分类和流式令牌级内容检测。</li></ul><h2 id="六、agent能力与开源生态" tabindex="-1">六、Agent能力与开源生态 <a class="header-anchor" href="#六、agent能力与开源生态" aria-label="Permalink to &quot;六、Agent能力与开源生态&quot;">​</a></h2><h3 id="_6-1-agentscope框架" tabindex="-1">6.1 AgentScope框架 <a class="header-anchor" href="#_6-1-agentscope框架" aria-label="Permalink to &quot;6.1 AgentScope框架&quot;">​</a></h3><p>AgentScope1.0是一款以开发者为核心、专注多智能体开发的开源框架，包含三层技术架构：核心框架负责智能体构建与应用编排，Runtime提供安全运行环境，Studio提供可视化监控工具。框架已集成ReMe长期记忆实现，支持个人、任务和工具级别的长期记忆管理。</p><p>AgentScope开源了两个智能体应用：</p><ul><li><strong>Alias-Agent</strong>：具备任务规划和相应处理能力，可在ReAct、Planner-Executor、Deep Research、Browser-Use四种专业模式间智能切换。</li><li><strong>Data-Juicer Agent</strong>：多智能体系统，通过AgentScope的多智能体编排能力与Data-Juicer数据处理算子集成，实现自然语言驱动的数据处理。</li></ul><p>此外，AgentScope支持Agentic RL训练，只需少量代码适配即可使用Trinity-RFT框架进行强化学习。</p><h3 id="_6-2-桌面agent应用" tabindex="-1">6.2 桌面Agent应用 <a class="header-anchor" href="#_6-2-桌面agent应用" aria-label="Permalink to &quot;6.2 桌面Agent应用&quot;">​</a></h3><p>2026年4月，通义桌面Agent工具CoPaw更名为QwenPaw，正式纳入千问生态，聚焦于模型层的能力对齐，与千问系列模型在能力上做更紧密配合。</p><h3 id="_6-3-开源许可与使用政策" tabindex="-1">6.3 开源许可与使用政策 <a class="header-anchor" href="#_6-3-开源许可与使用政策" aria-label="Permalink to &quot;6.3 开源许可与使用政策&quot;">​</a></h3><p>Qwen系列主流模型采用Apache 2.0许可协议，允许商业使用且无需披露修改，这一策略显著降低了企业使用门槛。官方提供全流程开发工具链，包括数据预处理到模型部署的完整支持。</p><p>部署方式多样化：支持Ollama、llama.cpp、LM Studio等工具在本地运行，可通过阿里云DashScope API调用，或通过千问Chat免费使用。推理框架方面，支持Flash Attention、Paged Attention、各类量化方法（W8A8、W8A16、KV cache量化等）以及Multi LoRA等高级特性。</p><h2 id="七、性能评测" tabindex="-1">七、性能评测 <a class="header-anchor" href="#七、性能评测" aria-label="Permalink to &quot;七、性能评测&quot;">​</a></h2><h3 id="_7-1-多任务评测" tabindex="-1">7.1 多任务评测 <a class="header-anchor" href="#_7-1-多任务评测" aria-label="Permalink to &quot;7.1 多任务评测&quot;">​</a></h3><p><strong>Qwen2.5系列在MMLU（多任务语言理解）中得分达85+</strong>，在HumanEval代码生成和MATH数学评测中分别获得85+和80+的评分。Qwen2.5-72B在基准测试中表现尤为突出：MMLU得分89.7，超越Llama3 405B的87.2；HumanEval通过率78.3%，较Llama3 405B提升12个百分点；GSM8K数学推理准确率63.4%。更值得一提的是，Qwen2.5-9B在多个知识基准上直接超过了OpenAI的120B模型。</p><h3 id="_7-2-行业综合排名" tabindex="-1">7.2 行业综合排名 <a class="header-anchor" href="#_7-2-行业综合排名" aria-label="Permalink to &quot;7.2 行业综合排名&quot;">​</a></h3><p>在国际权威综合评分AA指数（Artificial Analysis Intelligence Index）中，Qwen3旗舰版本已跻身顶级模型行列，站在Grok 4.1和Claude 4.1身边，与Gemini3 Pro、GPT-5.1保持约7–10分的差距。在LMArena人类盲评Elo榜上，Qwen3旗舰虽略低于头部模型，但已混入第一梯队前列——海外开发者和研究者普遍评价Qwen3与GPT-5、Gemini3体验上不会拉开巨大差距。</p><p>在竞赛数学AIME2025中，Qwen3 235B处于第一梯队。Qwen3.5-Max-Preview于2026年3月在全球大模型竞技平台LMArena Expert榜单排名第10，超越GPT-5.4和Claude Opus 4.5。</p><h3 id="_7-3-视觉能力" tabindex="-1">7.3 视觉能力 <a class="header-anchor" href="#_7-3-视觉能力" aria-label="Permalink to &quot;7.3 视觉能力&quot;">​</a></h3><p>Qwen2-VL-72B在多模态基准测试中可与GPT-4o、Claude3.5-Sonnet等顶级模型相媲美。Qwen3-VL在视觉感知和多模态推理方面的表现更为突出，已在32项核心能力测评中超过Gemini2.5-Pro和GPT-5。</p><h2 id="八、应用与落地" tabindex="-1">八、应用与落地 <a class="header-anchor" href="#八、应用与落地" aria-label="Permalink to &quot;八、应用与落地&quot;">​</a></h2><h3 id="_8-1-行业应用" tabindex="-1">8.1 行业应用 <a class="header-anchor" href="#_8-1-行业应用" aria-label="Permalink to &quot;8.1 行业应用&quot;">​</a></h3><p>Qwen已广泛应用于企业级场景。制造业企业可通过Qwen2.5-72B构建智能运维系统。某金融科技公司将Qwen2.5-72B嵌入风控系统，通过微调实现反欺诈检测准确率提升27%。某医疗AI公司通过开源工具链在2周内完成影像诊断模型本地化部署，较传统方案节省60%时间。</p><p>截至2026年，超30万企业和机构在使用阿里云百炼平台，包括一汽、金山、哈啰集团、国家天文台等。Qwen生态还覆盖高德地图、淘宝闪购等生活服务应用。</p><h3 id="_8-2-api与平台" tabindex="-1">8.2 API与平台 <a class="header-anchor" href="#_8-2-api与平台" aria-label="Permalink to &quot;8.2 API与平台&quot;">​</a></h3><p>Qwen API与OpenAI API兼容。价格方面，Qwen3.5-Plus API定价约$0.26/百万输入tokens，较GPT-5系列便宜约70%。Qwen3-Max-Thinking比GPT-5.2便宜10–12倍。Qwen2.5-Turbo价格仅为0.3元/1M tokens，同时平台免费赠送1000万tokens额度。</p><h3 id="_8-3-c端产品" tabindex="-1">8.3 C端产品 <a class="header-anchor" href="#_8-3-c端产品" aria-label="Permalink to &quot;8.3 C端产品&quot;">​</a></h3><p>千问App实现语音交互、图像识别等功能，公测首周下载量超千万。App以Qwen3-Max/Qwen3-235B旗舰加Thinking版的组合为底座。2026年春节启动“春节请客计划”投入30亿推广。</p><h2 id="九、总结与展望" tabindex="-1">九、总结与展望 <a class="header-anchor" href="#九、总结与展望" aria-label="Permalink to &quot;九、总结与展望&quot;">​</a></h2><p>Qwen已从2023年的初代开源模型，发展为涵盖80余个主力模型、全栈多模态能力的完整AI生态，衍生模型超20万款。其在开源策略、性能表现和成本控制方面的综合优势，使其成为全球范围内企业采纳最多的开源模型之一。</p><p>展望未来，Qwen将持续沿着以下方向演进：一是MoE架构的进一步优化与专家模块的专业化；二是全模态统一模型的深度整合；三是长上下文处理效率和精度的持续提升；四是在Agent框架和具身智能方向的深入布局；五是在更广泛垂直领域的专用模型开发。</p>',88)])])}const u=t(o,[["render",d]]);export{c as __pageData,u as default};
